main.cpp:
#include <torch/torch.h>

struct IrisNet : torch::nn::Module {
    IrisNet() {
        fc1 = register_module("fc1", torch::nn::Linear(4, 100));
        fc2 = register_module("fc2", torch::nn::Linear(100, 100));
        fc3 = register_module("fc3", torch::nn::Linear(100, 3));
    }

    torch::Tensor forward(torch::Tensor x) {
        x = torch::relu(fc1->forward(x));
        x = torch::dropout(x, /*p=*/0.5, /*train=*/is_training());
        x = torch::relu(fc2->forward(x));
        x = torch::log_softmax(fc3->forward(x), /*dim=*/1);
        return x;
    }

    torch::nn::Linear fc1{nullptr}, fc2{nullptr}, fc3{nullptr};
};

using namespace torch::indexing;

class IrisDataset : public torch::data::Dataset<IrisDataset> {
public:
    explicit IrisDataset(c10::Device type) {
        features_ = at::tensor(
                {
                        5.1, 3.5, 1.4, 0.2,
                        4.9, 3.0, 1.4, 0.2,
                        4.7, 3.2, 1.3, 0.2,
                },
                type
        ).reshape({3, 4});

        targets_ = at::tensor(
                {
                        0,
                        0,
                        0,
                },
                type
        ).toType(c10::ScalarType::Long);

    }

    torch::data::Example<> get(size_t index) override {
        return {features_.index({int(index)}), targets_.index({int(index)})};
    }

    [[nodiscard]] c10::optional<size_t> size() const override {
        return 3;
    }

private:
    torch::Tensor features_, targets_;
};

int main() {
    auto net = std::make_shared<IrisNet>();

    c10::DeviceType type = torch::kMPS;

    net->to(type);

    auto dataset = IrisDataset(type);

    auto data_loader = torch::data::make_data_loader(
            dataset.map(torch::data::transforms::Stack<>()),
            /*batch_size=*/1);

    torch::optim::Adam optimizer(net->parameters(), /*lr=*/0.01);

    for (size_t epoch = 1; epoch <= 10; ++epoch) {
        size_t batch_index = 0;
        for (auto &batch: *data_loader) {
            optimizer.zero_grad();
            torch::Tensor prediction = net->forward(batch.data);
            torch::Tensor loss = torch::nll_loss(prediction, batch.target);
            loss.backward();
            optimizer.step();
            if (++batch_index % 1 == 0) {
                std::cout << "Epoch: " << epoch << " | Batch: " << batch_index
                          << " | Loss: " << loss.item<float>() << std::endl;
            }
        }
    }
    return 0;
}

